  "screens/documents-10": "{{{top}}}<form id=\"rms-application-filter\" class=\"rms-filter\"><div class=\"rms-fieldgrid\">{{{selectHtml}}}{{{fieldHtml}}}{{{fieldHtml2}}}</div></form><section class=\"rms-panel\"><div class=\"rms-panelhead\"><h2>{{title}}</h2>{{{badgeHtml}}}</div><dl class=\"rms-profile\"><div><dt>기업명</dt><dd>{{companyName}}</dd></div><div><dt>대표자</dt><dd>{{representative}}</dd></div><div class=\"rms-wide\"><dt>신청서 주소</dt><dd>{{inputAddress}}</dd></div></dl>{{{value}}}<div class=\"rms-panelhead\"><h2>접수서류</h2>{{{value2}}}</div><div class=\"rms-statusrow\">{{{itemsHtml}}}</div>{{{tableHtml}}}<p class=\"rms-muted rms-space\">9종은 우선 연계대상입니다. 필수 여부는 사업별로 다릅니다. 서류당 한 파일을 선택하며 여러 파일은 ZIP으로 묶습니다.</p><div class=\"rms-actions rms-space\">{{{btnHtml}}}{{{value3}}}{{{btnHtml2}}}</div></section>",
  "screens/documents-11": "<label class=\"rms-consent\"><input type=\"checkbox\" id=\"rms-consent\"{{{value}}}{{{value2}}}><span><strong>증빙서류 조회를 위한 정보 제공에 동의합니다.</strong><small>목적: {{title}} 신청서류 확인 · 항목: 선택한 증빙서류와 기업 기본정보<br>제공대상: 해당 사업 관리기관 · 보유기간/동의문은 실연계 전 협의가 필요합니다.<br>현재는 실제 동의 효력이 없는 시연입니다. 동의하지 않아도 파일 제출로 진행할 수 있습니다.</small></span></label>",
  "screens/documents-12": "<div class=\"rms-note\">기업 정보제공 동의: <b>{{{value}}}</b>{{{value2}}} · 기업별 서류를 확인하고 보완을 요청할 수 있습니다.</div>",
  "screens/documents-13": "<button type=\"button\" data-action=\"doc-status\" data-id=\"{{{k}}}\" aria-pressed=\"{{{value}}}\">{{{value2}}} {{{length}}}</button>",
  "screens/documents-14": "<tr><td>{{{value}}}</td><td><b>{{name}}</b><small>{{provider}}{{{value2}}}</small></td><td>{{{value3}}}</td><td>{{{badgeHtml}}}{{{value4}}}</td><td>{{{value5}}}</td><td><div class=\"rms-actions\">{{{btnHtml}}}{{{value6}}}{{{value7}}}{{{value8}}}</div></td></tr>",
  "screens/documents-15": "<span class=\"rms-required\">필수</span>",
  "screens/documents-16": "<small>{{reason}}</small>",
  "screens/documents-17": "{{name}}<small>파일명·크기만 보관</small>",
  "screens/documents-2": "{{{headHtml}}}<nav aria-label=\"사업신청 단계\"><ol class=\"rms-steps\">{{{itemsHtml}}}</ol></nav>",
  "screens/documents-3": "<li{{{value}}}><button type=\"button\" data-action=\"document-step\" data-id=\"{{{value2}}}\"{{{value3}}}>0{{{value4}}} {{{label}}}</button></li>",
  "screens/documents-4": "{{{top}}}<section class=\"rms-panel\"><h2>신청할 사업 선택</h2><p class=\"rms-muted rms-space\">현재 신청서: {{companyName}} / {{title}}</p><div class=\"rms-announcements rms-space\">{{{itemsHtml}}}</div><div class=\"rms-actions rms-space\">{{{btnHtml}}}</div></section>",
  "screens/documents-5": "<article class=\"rms-announcement\"><h3>{{title}}</h3><p>{{region}} · {{category}}</p><p><strong>접수기간</strong> {{start}} ~ {{end}}</p><p class=\"rms-program-deadline\"><strong>마감</strong> {{end2}} {{deadlineTime}}</p><div class=\"rms-actions\">{{{btnHtml}}}{{{itemsHtml}}}{{{value}}}</div></article>",
  "screens/documents-6": "{{{top}}}<section class=\"rms-panel\"><div class=\"rms-panelhead\"><h2>{{title}}</h2>{{{badgeHtml}}}</div><p class=\"rms-note\">{{{value}}}</p><form id=\"rms-company-form\" data-id=\"{{id}}\"><fieldset{{{value2}}}><div class=\"rms-fieldgrid rms-cols2\">{{{fieldHtml}}}{{{fieldHtml2}}}{{{fieldHtml3}}}</div></fieldset><p class=\"rms-muted rms-space\">기업 소재지: {{region}}{{{value3}}}</p><div class=\"rms-actions rms-space\">{{{btnHtml}}}{{{value4}}}{{{btnHtml2}}}</div></form></section>",
  "screens/documents-7": "<button type=\"submit\" class=\"rms-btn rms-btn-save\">기업정보 저장</button>",
  "screens/documents-8": "{{{top}}}<section class=\"rms-panel\"><div class=\"rms-panelhead\"><h2>{{title}} · {{companyName}}</h2>{{{badgeHtml}}}</div><p class=\"rms-note\">{{{value}}}</p>{{{tableHtml}}}<div class=\"rms-actions rms-space\">{{{btnHtml}}}{{{value2}}}</div></section>",
  "screens/documents-9": "<tr><td>{{name}}</td><td>{{{value}}}</td><td>{{{badgeHtml}}}</td><td>{{value2}}</td><td>{{{btnHtml}}}{{{value3}}}</td></tr>",
  "screens/documents": "{{{headHtml}}}{{{emptyHtml}}}<div class=\"rms-actions rms-space\">{{{btnHtml}}}</div>",
  "screens/faq-2": "<p class=\"rms-muted rms-space\">{{{value}}}</p>{{{faqListHtml}}}",
  "screens/faq-list-2": "<details><summary><span>{{title}}</span></summary><p>{{answer}}</p></details>",
  "screens/faq-list": "<div class=\"rms-faqs\">{{{itemsHtml}}}</div>",
  "screens/faq": "{{{headHtml}}}{{{tabsHtml}}}<section class=\"rms-panel\"><form id=\"rms-faq-search\" class=\"rms-searchbar\">{{{selectHtml}}}<div class=\"rms-field rms-span2\" ><label for=\"rms-faq-query\">검색어</label><input name=\"q\" id=\"rms-faq-query\" value=\"{{faqQuery}}\" placeholder=\"제목·내용·답변·키워드 검색\"></div><button class=\"rms-btn rms-btn-primary\" type=\"submit\">검색</button>{{{btnHtml}}}</form>{{{value}}}</section>",
  "screens/global-search": "<form id=\"rms-global-search\" class=\"rms-global-search\" role=\"search\"><label for=\"rms-global-query\">통합검색</label><input id=\"rms-global-query\" name=\"q\" value=\"{{value}}\" placeholder=\"사업공고, 기술닥터, 공지사항 등 필요한 정보를 검색하세요\" autocomplete=\"off\"><button class=\"rms-btn rms-btn-primary\" type=\"submit\">{{{homeIconHtml}}}<span>검색</span></button></form>",
  "screens/head-2": "<p class=\"rms-subtitle\">{{description}}</p>",
  "screens/head": "<div class=\"rms-pagehead\"><div><p class=\"rms-eyebrow\">REGIONAL MANAGEMENT SYSTEM</p><h1 id=\"rms-main\" tabindex=\"-1\">{{title}}</h1>{{{value}}}</div><div class=\"rms-pagecontext\">{{{value2}}}<p class=\"rms-breadcrumb\">홈 &nbsp;›&nbsp; {{value3}}</p></div></div>",
  "screens/home-boards-2": "<section class=\"rms-board-panel\"><div class=\"rms-board-panelhead\"><h2>{{itemValue}}</h2><a href=\"#boards/{{{type}}}\" aria-label=\"{{itemValue2}} 더보기\">더보기 {{{homeIconHtml}}}</a></div><ul class=\"rms-board-preview\">{{{boardRowsHtml}}}</ul></section>",
  "screens/home-boards": "<div class=\"rms-home-boards\" aria-label=\"공개 게시판\">{{{itemsHtml}}}</div>",
